import{z as d,x as A,o as t,c as B,q as o,j as l,D as r,d as E,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"死代码消除与 ADCE","description":"","frontmatter":{"title":"死代码消除与 ADCE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dce-adce.md","filePath":"cs/dce-adce.md","lastUpdated":1791063341000}'),D={name:"cs/dce-adce.md"};function p(C,a,c,u,h,m){const s=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=o('<h1 id="死代码消除与-adce" tabindex="-1">死代码消除与 ADCE <a class="header-anchor" href="#死代码消除与-adce" aria-label="Permalink to &quot;死代码消除与 ADCE&quot;">​</a></h1><div class="epigraph"><p>若赋值的结果从不被观察，且运算无副作用，则可删。激进 DCE 从必要指令反推，未碰到的一律死。</p><footer>—— 据 Cytron 等 SSA；Muchnick, Advanced Compiler Design；LLVM ADCE 实践；龙书死代码整理</footer></div><p>上一课<a href="/cs/cse-gvn">CSE/GVN</a>留下拷贝与可删的重复运算。缺口是<strong>死代码</strong>：无用赋值、不可达块、SCCP 钉死的枝。普通 DCE 看 def-use；ADCE（aggressive）从「必要」种子（store、return、volatile、有副作用的调用）沿反向依赖与控制依赖扩张。本课钉必要集，不写完整 CDG 算法细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SSA 上：若名无 use 且右部纯，删赋值。φ 的 use 没了可再删，迭代。控制流：条件若只服务死赋值，分支可折成跳转。缺口是<strong>观察点</strong>，不是值编号。</p><p><span class="marginnote">直觉类比：ADCE 像从出口倒着照亮房间——先点亮所有观察点（store、return、volatile），光沿数据依赖和控制依赖回溯，没被照到的指令一律算死；普通 DCE 只检查「没人引用的变量」，照不到控制流层面的死枝，这是「激进」二字的分量。</span></p><p>副作用：<code>free</code>、IO、<code>volatile</code> 是种子。语言若允许省略无观察的 store，规则随内存模型——后课 UB。</p><h3 id="死不是「程序员没读变量」" tabindex="-1">死不是「程序员没读变量」 <a class="header-anchor" href="#死不是「程序员没读变量」" aria-label="Permalink to &quot;死不是「程序员没读变量」&quot;">​</a></h3><p>逃逸到内存、通过指针读，算观察。无<a href="/cs/alias-analysis">别名分析</a> 时，对 store 必须保守当活。本课标量 SSA 可激进；内存保守。</p><p><span class="marginnote">常见误区：初学者容易以为「变量后面没被读过」就能删。若赋值写进了内存、指针还可能把它读出来，这就算观察——没有别名分析背书时，对 store 必须保守当活，否则优化会静默改变程序语义。</span></p><p><span class="marginnote">Muchnick 有 DCE 章。Cytron 指出 SSA 使死代码显然。Ferrante 等控制依赖。LLVM 的 ADCE/BDCE 是工程名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标记：从种子工作表反向：指令的操作数变必要；控制依赖的分支变必要。未标记删除。不可达块：CFG 从入口 DFS。</p>',13)),(t(),l(i,null,{default:r(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E5%89%AF%E4%BD%9C%E7%94%A8%20%2F%20%E8%BF%94%E5%9B%9E%22%5D%20--%3E%20REV%5B%22%E5%8F%8D%E5%90%91%E4%BE%9D%E8%B5%96%22%5D%0A%20%20REV%20--%3E%20LIVE%5B%22%E5%BF%85%E8%A6%81%E6%8C%87%E4%BB%A4%22%5D%0A%20%20LIVE%20--%3E%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%85%B6%E4%BD%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 SCCP：不可执行边先删，减少种子。二者顺序可迭代至不动点。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"调试信息：删指令要决定是否保留位置——DWARF 后课。不要把 ADCE 当混淆器的「删所有」；种子错则改变语义。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"为什么重要：种子集选错——比如漏掉一个带副作用的调用——ADCE 就会把活代码删掉，程序静默变错且不报任何错。ADCE 难写的根源在此：正确性全押在「必要集」是否完备上。")],-1)),(t(),l(i,null,{default:r(()=>[n(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%B5%8B%E5%80%BC%20x%20%E6%97%A0%20use%22%5D%20--%3E%20B%5B%22%E5%88%A0%E9%99%A4%E8%B5%8B%E5%80%BC%22%5D%0A%20%20B%20--%3E%20C%5B%22%CF%86%20%E5%B0%91%E4%BA%86%E4%B8%80%E6%9D%A1%E5%85%A5%E8%BE%B9%22%5D%0A%20%20C%20--%3E%20D%5B%22%CF%86%20%E4%B9%9F%E4%B8%8D%E5%86%8D%E5%BF%85%E8%A6%81%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%88%86%E6%94%AF%E6%9D%A1%E4%BB%B6%E5%8F%AA%E6%9C%8D%E5%8A%A1%E6%AD%BB%E8%B5%8B%E5%80%BC%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%88%86%E6%94%AF%E6%8A%98%E5%8F%A0%E6%88%90%E6%97%A0%E6%9D%A1%E4%BB%B6%E8%B7%B3%E8%BD%AC%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>无穷循环无副作用：C++ 曾允许删除，现更谨慎；这是语言律师问题，分析须按所选标准。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写部分死（某些路径死）。后课默认：无观察的纯赋值可删。下一课 LICM：活但循环不变的计算往外搬，不是删。</p><p>也不把 DCE 当链接期 GC 节。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DCE 删无 use 的纯赋值；ADCE 从观察点反推必要集。</li><li>内存与副作用必须当种子或保守。</li><li>与 SCCP 交替，清死枝。</li><li>出处：Cytron et al.；Muchnick；对照龙书；Ferrante 控制依赖。</li></ul>',6))])}const _=d(D,[["render",p]]);export{S as __pageData,_ as default};
